\title{Cographs Are a Self-Complementary Hereditary Class:\\
The Structural Foundation for Generalized Spectral Closure}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\maketitle

\begin{abstract}
A graph is a \emph{cograph} if it contains no induced path on four vertices,
$P_4$; equivalently, cographs are exactly the graphs generated from a single
vertex by disjoint union and join. Cographs are central to the theory of
\emph{generalized spectral characterizations}, in which one asks whether a graph
is determined by the pair consisting of its adjacency spectrum and the spectrum
of its complement. We isolate and prove the structural backbone that makes the
complement spectrum the correct companion invariant for this class. First,
complementation is \emph{functorial} on induced embeddings: an induced embedding
$G \hookrightarrow H$ yields an induced embedding $G^\comp \hookrightarrow
H^\comp$ on the same vertex map. Second, the path $P_4$ is
\emph{self-complementary}, $P_4 \cong P_4^\comp$, via the explicit permutation
$0\,1\,2\,3 \mapsto 1\,3\,0\,2$. Together these give the central result: the
class of cographs is \emph{closed under complementation}. Fourth, the algebraic
bridge $A(G^\comp) = J - I - A(G)$ couples the complement spectrum to the
adjacency spectrum, and the two-spectrum invariant (generalized cospectrality) is
itself closed under complementation, acting by swapping its components. We record
the hereditary and isomorphism-invariance properties of cographs and formulate
the conjecture that cographs are generalized spectrally closed.
\end{abstract}

\noindent\textbf{Keywords:} cograph, forbidden induced subgraph, $P_4$,
self-complementary graph class, adjacency spectrum, generalized cospectrality,
threshold graph, hereditary class.

\section{Introduction}

\subsection{Spectral determination}
A finite simple graph $G$ on vertex set $V$ has an \emph{adjacency matrix}
$A(G)$, the symmetric $0/1$ matrix whose $(u,v)$ entry is $1$ exactly when $u$
and $v$ are adjacent. The multiset of eigenvalues of $A(G)$ is the
\emph{adjacency spectrum}. Two graphs with the same spectrum are
\emph{cospectral}, and cospectral non-isomorphic graphs abound, so the spectrum
alone generally fails to determine a graph.

A refinement that dramatically improves matters records, in addition, the
spectrum of the \emph{complement}. Two graphs $G$ and $H$ on the same vertex set
are \emph{generalized cospectral} when they share the characteristic polynomial
of the adjacency matrix \emph{and} that of the complement adjacency matrix.

\subsection{Self-complementary forbidden-subgraph classes}
A hereditary class $\mathcal C$ is \emph{generalized spectrally closed} if every
graph generalized cospectral with a member of $\mathcal C$ is again a member. A
natural heuristic: a class defined by forbidding a \emph{self-complementary}
configuration ought to be governed by a \emph{self-complementary} invariant, and
generalized cospectrality is exactly such an invariant. We make this precise for
\textbf{cographs}, the graphs with no induced $P_4$. The known generalized
spectral characterization of \textbf{threshold graphs},
$\Forb(2K_2, P_4, C_4)$, is the motivating precedent.

\section{Definitions and conventions}
Graphs are finite, simple, undirected. We write $u \sim_G v$ for adjacency.

\begin{definition}[Complement]
The \emph{complement} $G^\comp$ has the same vertex set, with $u
\sim_{G^\comp} v$ iff $u \neq v$ and $u \not\sim_G v$. Complementation is an
involution: $(G^\comp)^\comp = G$.
\end{definition}

\begin{definition}[Induced embedding]
An \emph{induced embedding} $f : G \hookrightarrow H$ is an injection of vertex
sets with $a \sim_G b \iff f(a) \sim_H f(b)$ for all $a,b$. A bijective induced
embedding is an \emph{isomorphism}.
\end{definition}

\begin{definition}[The path $P_4$]
$P_4$ is the graph on $\{0,1,2,3\}$ with edges $\{0,1\},\{1,2\},\{2,3\}$.
\end{definition}

\begin{definition}[Cograph]
$G$ is a \emph{cograph} if there is no induced embedding $P_4 \hookrightarrow G$;
equivalently, $G$ is constructible from single vertices by disjoint union and
join.
\end{definition}

\begin{definition}[Generalized cospectral]
Graphs $G,H$ on a common finite vertex set are \emph{generalized cospectral} if
$\chi_{A(G)} = \chi_{A(H)}$ and $\chi_{A(G^\comp)} = \chi_{A(H^\comp)}$, where
$\chi_M$ is the characteristic polynomial. Here $J$ is the all-ones matrix and
$I$ the identity of size $|V|$.
\end{definition}

\section{The complement functor on induced embeddings}

\begin{theorem}[Complement functor]\label{thm:functor}
If $f : G \hookrightarrow H$ is an induced embedding, then the same underlying
vertex map is an induced embedding $f : G^\comp \hookrightarrow H^\comp$.
\end{theorem}

\begin{proof}
$f$ is injective; it remains to preserve and reflect adjacency in the
complements. Fix $a,b$. If $a \sim_{G^\comp} b$, i.e. $a \neq b$ and $a
\not\sim_G b$, then $f(a) \neq f(b)$ by injectivity and $f(a) \not\sim_H f(b)$
since $f$ reflects adjacency; hence $f(a) \sim_{H^\comp} f(b)$. Conversely, if
$f(a) \sim_{H^\comp} f(b)$, then $f(a) \neq f(b)$ forces $a \neq b$, and $f(a)
\not\sim_H f(b)$ forces $a \not\sim_G b$; hence $a \sim_{G^\comp} b$. Thus $a
\sim_{G^\comp} b \iff f(a) \sim_{H^\comp} f(b)$.
\end{proof}

Consequently, forbidden-induced-subgraph classes transport across complements: if
$F$ embeds induced in $G$, then $F^\comp$ embeds induced in $G^\comp$.

\section{The path $P_4$ is self-complementary}

\begin{theorem}[Chameleon Lemma]\label{thm:cham}
$P_4$ is self-complementary: $P_4 \cong P_4^\comp$, via
$\sigma : 0 \mapsto 1,\ 1 \mapsto 3,\ 2 \mapsto 0,\ 3 \mapsto 2$
(inverse $0 \mapsto 2,\ 1 \mapsto 0,\ 2 \mapsto 3,\ 3 \mapsto 1$).
\end{theorem}

\begin{proof}
Edges of $P_4$ are $\{0,1\},\{1,2\},\{2,3\}$; edges of $P_4^\comp$ are
$\{0,2\},\{0,3\},\{1,3\}$. Checking all six unordered pairs:
\[
\begin{array}{c|c|c|c}
\{a,b\} & \text{edge in } P_4? & \{\sigma a,\sigma b\} & \text{edge in } P_4^\comp? \\ \hline
\{0,1\} & \text{yes} & \{1,3\} & \text{yes} \\
\{1,2\} & \text{yes} & \{3,0\} & \text{yes} \\
\{2,3\} & \text{yes} & \{0,2\} & \text{yes} \\
\{0,2\} & \text{no}  & \{1,0\} & \text{no} \\
\{0,3\} & \text{no}  & \{1,2\} & \text{no} \\
\{1,3\} & \text{no}  & \{3,2\} & \text{no}
\end{array}
\]
Edges map to edges and non-edges to non-edges, so $\sigma$ is an isomorphism.
\end{proof}

\section{Cographs form a self-complementary hereditary class}

\begin{lemma}[Complementing an induced $P_4$]\label{lem:comp}
If $G$ contains an induced $P_4$, then $G^\comp$ contains an induced $P_4$.
\end{lemma}

\begin{proof}
Let $e : P_4 \hookrightarrow G$ be induced. By Theorem~\ref{thm:functor}, $e$ is
an induced embedding $P_4^\comp \hookrightarrow G^\comp$. By
Theorem~\ref{thm:cham} there is an isomorphism $\sigma : P_4 \cong P_4^\comp$, so
$e \circ \sigma : P_4 \hookrightarrow G^\comp$ is induced.
\end{proof}

\begin{theorem}[Closure under complementation]\label{thm:selfcomp}
$G$ is a cograph iff $G^\comp$ is a cograph.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:comp}, $G$ has an induced $P_4$ implies $G^\comp$ does. Applying
the lemma to $G^\comp$ and using $(G^\comp)^\comp = G$ gives the converse. Hence
$G$ has no induced $P_4$ iff $G^\comp$ has none.
\end{proof}

\begin{theorem}[Hereditary property]\label{thm:hered}
If $f : G \hookrightarrow H$ is induced and $H$ is a cograph, then $G$ is a
cograph.
\end{theorem}

\begin{proof}
If $e : P_4 \hookrightarrow G$ were induced, then $f \circ e : P_4 \hookrightarrow
H$ would be induced, contradicting that $H$ is a cograph.
\end{proof}

\begin{theorem}[Isomorphism invariance]\label{thm:iso}
If $G \cong H$, then $G$ is a cograph iff $H$ is.
\end{theorem}

\begin{proof}
An isomorphism is an induced embedding both ways; apply Theorem~\ref{thm:hered}.
\end{proof}

\section{The algebraic bridge to spectra}
Fix a finite vertex set $V$ and work over $\mathbb{Q}$.

\begin{theorem}[Complement adjacency identity]\label{thm:AJI}
For every graph $G$ on $V$, $\; A(G^\comp) = J - I - A(G)$.
\end{theorem}

\begin{proof}
Compare entries $(v,w)$. If $v=w$: both sides are $0$. If $v \neq w$: $(J-I)_{vw}
= 1$; if $v \sim_G w$ both sides equal $1-1=0$, and if $v \not\sim_G w$ both sides
equal $1-0=1$.
\end{proof}

\begin{remark}
Since $J$ does not commute with $A(G)$ in general, the eigenvalues of $J-I-A(G)$
are not mere shifts of those of $A(G)$; the complement spectrum carries genuinely
new information while remaining rigidly tied to $A(G)$.
\end{remark}

\begin{theorem}[Invariant closed under complementation]\label{thm:invcomp}
If $G$ and $H$ are generalized cospectral, then so are $G^\comp$ and $H^\comp$.
\end{theorem}

\begin{proof}
Generalized cospectrality of $G^\comp, H^\comp$ requires $\chi_{A(G^\comp)} =
\chi_{A(H^\comp)}$ (the second clause of the hypothesis) and
$\chi_{A(G^{\comp\comp})} = \chi_{A(H^{\comp\comp})}$, which by involutivity is
$\chi_{A(G)} = \chi_{A(H)}$ (the first clause). Complementation swaps the two
clauses.
\end{proof}

\section{Toward generalized spectral closure}

\begin{conjecture}[Cographs are generalized spectrally closed]
If $G$ is a cograph and $H$ is generalized cospectral with $G$, then $H$ is a
cograph.
\end{conjecture}

\begin{conjecture}[Induced-$P_4$ count as a joint spectral moment]
The number of induced copies of $P_4$ in a graph is a polynomial in the moments
$\tr A(G)^k$ and $\tr A(G^\comp)^k$, hence determined by generalized
cospectrality. Via Theorem~\ref{thm:AJI}, every $\tr A(G^\comp)^k$ is a symmetric
function of $J, I, A(G)$ and thus a joint spectral moment.
\end{conjecture}

\begin{conjecture}[Spectral detectability governs closure]
For a finite family $F$ closed under complementation, $\Forb(F)$ is generalized
spectrally closed precisely when, for each $H \in F$, containing $H$ as an induced
subgraph is determined by the joint spectra. Cographs ($F=\{P_4\}$) are the
minimal nontrivial instance.
\end{conjecture}

\begin{conjecture}[Threshold graphs factor through cographs]
Threshold graphs $\Forb(2K_2, P_4, C_4)$ sit strictly inside the cograph closure:
their generalized-cospectral mates are exactly their cograph mates avoiding
$2K_2$ and $C_4$.
\end{conjecture}

\section{Algorithms}
\textbf{Cograph recognition.} Enumerate all $\binom{n}{4}$ quadruples and test
for an induced $P_4$; $O(n^4)$.
\textbf{Complement transport.} Reuse the same vertex map (Theorem~\ref{thm:functor}).
\textbf{Generalized-cospectrality test.} Form $A(G), A(H)$ and their complements
via Theorem~\ref{thm:AJI}, compute four characteristic polynomials, compare;
$O(n^3)$ each.

\section{Conclusion}
Cographs form a self-complementary hereditary class: complementation is
functorial on induced embeddings (Theorem~\ref{thm:functor}), $P_4$ is
self-complementary (Theorem~\ref{thm:cham}), hence the class is closed under
complementation (Theorem~\ref{thm:selfcomp}), hereditary
(Theorem~\ref{thm:hered}), and an isomorphism invariant (Theorem~\ref{thm:iso}).
The identity $A(G^\comp) = J - I - A(G)$ (Theorem~\ref{thm:AJI}) couples the two
spectra, and the two-spectrum invariant is itself self-complementary
(Theorem~\ref{thm:invcomp}). These pinpoint generalized cospectrality as the
natural invariant for cographs and motivate the conjecture that cographs are
generalized spectrally closed.

\end{document}

