"""Demo: recognizing cographs by brute-force induced-P4 search."""
from __future__ import annotations
from itertools import combinations, permutations

def adjacent(edges: set[frozenset[int]], u: int, v: int) -> bool:
    return frozenset((u, v)) in edges

def induced_has_p4(n: int, edges: set[frozenset[int]]) -> bool:
    """True iff the graph on n vertices contains an induced path P4."""
    p4_edges = {frozenset((0, 1)), frozenset((1, 2)), frozenset((2, 3))}
    for quad in combinations(range(n), 4):
        idx = {v: i for i, v in enumerate(quad)}
        sub = {frozenset((idx[u], idx[v]))
               for u, v in combinations(quad, 2) if adjacent(edges, u, v)}
        for perm in permutations(range(4)):
            mapped = {frozenset((perm[u], perm[v])) for e in p4_edges
                      for u, v in [tuple(e)]}
            if mapped == sub:
                return True
    return False

def is_cograph(n: int, edge_list: list[tuple[int, int]]) -> bool:
    edges = {frozenset(e) for e in edge_list}
    return not induced_has_p4(n, edges)

if __name__ == "__main__":
    print("K4      :", is_cograph(4, list(combinations(range(4), 2))))   # True
    print("P4      :", is_cograph(4, [(0, 1), (1, 2), (2, 3)]))          # False
    print("C4      :", is_cograph(4, [(0, 1), (1, 2), (2, 3), (3, 0)]))  # True
    print("P5      :", is_cograph(5, [(0, 1), (1, 2), (2, 3), (3, 4)]))  # False

"""Demo: verifying that P4 is self-complementary via 0 1 2 3 -> 1 3 0 2."""
from __future__ import annotations
from itertools import combinations

def path4_edges() -> set[frozenset[int]]:
    return {frozenset((0, 1)), frozenset((1, 2)), frozenset((2, 3))}

def complement_edges(n: int, edges: set[frozenset[int]]) -> set[frozenset[int]]:
    return {frozenset(p) for p in combinations(range(n), 2)
            if frozenset(p) not in edges}

def is_iso(n: int, g: set[frozenset[int]], h: set[frozenset[int]],
           perm: list[int]) -> bool:
    for u, v in combinations(range(n), 2):
        if (frozenset((u, v)) in g) != (frozenset((perm[u], perm[v])) in h):
            return False
    return True

if __name__ == "__main__":
    p4 = path4_edges()
    p4c = complement_edges(4, p4)
    sigma = [1, 3, 0, 2]
    print("P4  edges :", sorted(tuple(sorted(e)) for e in p4))
    print("P4^c edges:", sorted(tuple(sorted(e)) for e in p4c))
    print("sigma is an isomorphism P4 -> P4^c :", is_iso(4, p4, p4c, sigma))

